import threading
import psycopg

def reproduce(connect, service) -> str | None:
    # Discover balances to pick a good victim (small positive balance drains fast)
    with connect() as conn:
        rows = conn.execute("SELECT id, balance FROM accounts ORDER BY id").fetchall()
    # pick account 1 if it has positive balance, else smallest positive
    victim = None
    victim_bal = None
    for _id, _bal in rows:
        if _id in (1, 2) and _bal and _bal > 0:
            victim, victim_bal = _id, _bal
            break
    if victim is None:
        # smallest positive balance account
        cands = [(i, b) for i, b in rows if b and b > 0]
        if not cands:
            return None
        cands.sort(key=lambda x: x[1])
        # prefer a modest balance (not the richest) for reliable drain
        victim, victim_bal = cands[0][0], cands[0][1]
    amount = max(1, victim_bal // 8)
    N = 40
    # pre-open one connection per thread so barrier syncs the actual requests
    conns = [connect() for _ in range(N)]
    barrier = threading.Barrier(N + 1)
    def worker(c):
        try:
            barrier.wait(timeout=15)
        except Exception:
            return
        try:
            try:
                service.withdraw(c, victim, amount)
            except service.InsufficientFunds:
                pass
            except ValueError:
                pass
            except Exception:
                pass
        finally:
            try:
                c.close()
            except Exception:
                pass
    threads = [threading.Thread(target=worker, args=(conns[i],)) for i in range(N)]
    for t in threads:
        t.start()
    try:
        barrier.wait(timeout=15)
    except Exception:
        pass
    for t in threads:
        t.join(timeout=30)
    with connect() as conn:
        row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (victim,)).fetchone()
        final = row[0] if row else None
    if final is not None and final < 0:
        return f"overdraft violated: account {victim} initial={victim_bal} amount={amount} x{N} final={final} went negative"
    return None

